-- Y'a du peuple ? — Horaires d'ouverture des 42 restos (relevés sur Google Maps le 11/11/2026)
-- À valider par Alexis avant exécution. Ne supprime rien.
-- hours = 7 listes (0 = dimanche … 6 = samedi) de plages [ouverture, fermeture] en minutes depuis minuit.
-- Une fermeture après minuit dépasse 1440 (ex. 08:30–01:00 = [510, 1500]).
-- Jour férié (11 novembre) : remplacé par les horaires d'un jour normal.

create table if not exists public.opening_hours (
  establishment_id uuid primary key references public.establishments(id) on delete cascade,
  hours jsonb not null,
  source text not null default 'google_maps',
  updated_at timestamptz not null default now()
);
alter table public.opening_hours enable row level security;
drop policy if exists "opening_hours lecture publique" on public.opening_hours;
create policy "opening_hours lecture publique" on public.opening_hours for select using (true);
grant select on public.opening_hours to anon, authenticated;

on conflict (establishment_id) do update set hours = excluded.hours, updated_at = now();
